const clean = (s: string) => s.replaceAll("/", "-").trim();
// Plan: source -> target
const plan: [string, string][] = [];
const used = new Set<string>(readdirSync(dir));
const claimed = new Set<string>();
for (const [f, a, t] of rows) {
  let base = `${clean(a)} - ${clean(t)}`;
  let tgt = `${base}.mp3`;
